INSERT INTO `feedback` VALUES (1,9,5,'design','Very clean design, the dark mode looks great on my phone.',NULL,'/','mobile','read','2026-11-17 07:10:00'),(2,10,4,'idea','Would be nice to filter dishes by calories for my diet.',NULL,'/restaurants?mode=dishes','desktop','new','2026-11-21 07:03:00'),(3,NULL,3,'usability','It took me a while to find where to write a review.',NULL,'/restaurant?id=2','mobile','new','2026-11-22 07:09:00');
