/*!40000 ALTER TABLE `restaurants` DISABLE KEYS */;
INSERT INTO `restaurants` VALUES (1,2,1,'Dastarkhan House','A warm family restaurant serving traditional Kazakh cuisine the way grandmothers make it: slow-cooked beshbarmak, crispy baursaks straight from the pan and endless pots of milky tea. Large tables for celebrations and a quiet hall for business lunches.','Aktobe','Abilkayyr Khan Ave 42','+7 7132 55 12 34',NULL,2,'10:00:00','23:00:00','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=70','approved',1,'2025-11-28 07:22:00','2026-11-23 17:04:34'),(2,3,2,'Trattoria Bella Notte','Neapolitan wood-fired pizza, fresh pasta made every morning and a short list of Italian wines. Candle-lit tables, an open kitchen and a terrace with mountain views in summer.','Almaty','Dostyk Ave 128','+7 727 312 44 10',NULL,3,'12:00:00','23:30:00','https://images.unsplash.com/photo-1574071318508-1cdbab80d002?auto=format&fit=crop&w=1200&q=70','approved',1,'2025-12-07 07:42:00','2026-11-23 17:04:34'),(3,4,3,'Sakura Garden','An elegant sushi bar where the chef prepares nigiri and rolls in front of you. Fish is delivered twice a week, and the omakase counter has only eight seats — book ahead.','Astana','Kabanbay Batyr Ave 15','+7 7172 70 20 30',NULL,4,'12:00:00','23:00:00','https://images.unsplash.com/photo-1553621042-f6e147245754?auto=format&fit=crop&w=1200&q=70','approved',1,'2025-12-16 07:49:00','2026-11-23 17:04:34'),(4,5,4,'Anatolia Grill','Charcoal-grilled kebabs, freshly baked lahmacun and Turkish tea until midnight. Quick lunches on weekdays and a lively atmosphere in the evenings.','Aktobe','Sankibai Batyr Ave 9','+7 7132 90 11 22',NULL,2,'11:00:00','00:00:00','https://images.unsplash.com/photo-1529006557810-274b9b2fc783?auto=format&fit=crop&w=1200&q=70','approved',0,'2025-12-25 07:34:00','2026-11-23 17:04:34'),(5,5,5,'Tbilisi Courtyard','Georgian hospitality in a green inner courtyard: juicy khinkali, bubbling khachapuri and live polyphonic music on Friday nights.','Almaty','Abay Ave 77','+7 727 250 60 70',NULL,3,'12:00:00','00:00:00','https://images.unsplash.com/photo-1552566626-52f8b828add9?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-01-03 07:11:00','2026-11-23 17:04:34'),(6,6,6,'Smoke & Stack Burgers','Smash burgers on potato buns, slow-smoked ribs and thick milkshakes. Loud music, sports on the big screen and the best fries in town.','Aktobe','Mametova St 21','+7 7132 44 88 00',NULL,2,'11:00:00','23:00:00','https://images.unsplash.com/photo-1572802419224-296b0aeee0d9?auto=format&fit=crop&w=1200&q=70','approved',1,'2026-01-12 07:48:00','2026-11-23 17:04:34'),(7,4,7,'Seoul Kitchen','Korean home cooking and street food: crispy fried chicken, sizzling stone-pot bibimbap and plenty of kimchi on the side.','Astana','Turan Ave 37','+7 7172 55 66 77',NULL,2,'11:00:00','22:00:00','https://images.unsplash.com/photo-1498654896293-37aacf113fd9?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-01-21 07:27:00','2026-11-23 17:04:34'),(8,5,8,'Spice Route','North Indian curries from the tandoor and slow-cooked biryanis. Spice level is adjustable — just ask your waiter.','Almaty','Tole Bi St 55','+7 727 300 12 12',NULL,3,'12:00:00','23:00:00','https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-01-30 07:04:00','2026-11-23 17:04:34'),(9,2,9,'Samarkand Plov Centre','Plov cooked in a huge kazan over fire every morning — come before 2 pm, it sells out! Simple interior, fast service and honest prices.','Aktobe','Bratyev Zhubanovykh St 270','+7 7132 21 21 21',NULL,1,'09:00:00','21:00:00','https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-02-08 07:53:00','2026-11-23 17:04:34'),(10,4,10,'Golden Dragon','Cantonese and Sichuan classics in a spacious dining hall with round tables — great for groups and family dinners.','Astana','Mangilik El Ave 20','+7 7172 40 50 60',NULL,2,'11:00:00','23:00:00','https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-02-17 07:06:00','2026-11-23 17:04:34'),(11,3,11,'Le Petit Café','A Parisian-style café for slow breakfasts and afternoon pastries. Croissants are baked on site every morning; the terrace is perfect for people-watching.','Almaty','Panfilov St 98','+7 727 222 33 44',NULL,2,'08:00:00','21:00:00','https://images.unsplash.com/photo-1484723091739-30a097e8f929?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-02-26 07:48:00','2026-11-23 17:04:34'),(12,6,12,'Green Leaf Bowl','100% vegetarian kitchen with plenty of vegan options. Colourful bowls, fresh smoothies and a calm, plant-filled interior.','Aktobe','Abay Ave 50','+7 7132 33 22 11',NULL,2,'09:00:00','21:00:00','https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=1200&q=70','approved',1,'2026-03-07 07:09:00','2026-11-23 17:04:34'),(13,6,13,'Casa Mexicana','Tacos, burritos and loud mariachi Saturdays. Colourful decor and a menu that goes from mild to \"muy picante\".','Astana','Dostyk St 5','+7 7172 99 88 77',NULL,2,'12:00:00','00:00:00','https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-03-16 07:03:00','2026-11-23 17:04:34'),(14,2,14,'Steppe Steakhouse','Premium dry-aged Kazakh beef grilled over birch charcoal. Dark wood, leather chairs and a serious wine cellar — the place for special occasions.','Astana','Kunayev St 12','+7 7172 77 00 77',NULL,4,'13:00:00','00:00:00','https://images.unsplash.com/photo-1600891964092-4316c288032e?auto=format&fit=crop&w=1200&q=70','approved',1,'2026-03-25 07:25:00','2026-11-23 17:04:34'),(15,6,15,'Sweet Crumbs Bakery','Small neighbourhood bakery with donuts, layered cakes and the best cinnamon rolls in Aktobe. Everything is baked in the morning and sold out by evening.','Aktobe','Moldagulova Ave 30','+7 7132 66 55 44',NULL,1,'08:00:00','20:00:00','https://images.unsplash.com/photo-1551024601-bec78aea704b?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-04-03 07:47:00','2026-11-23 17:04:34'),(16,3,16,'Ocean Pearl Seafood','Fresh fish and seafood flown in from the Caspian and the Black Sea. Bright, airy dining room with an open seafood counter.','Almaty','Al-Farabi Ave 140','+7 727 355 00 11',NULL,4,'12:00:00','23:00:00','https://images.unsplash.com/photo-1606850780554-b55ea4dd0b70?auto=format&fit=crop&w=1200&q=70','approved',0,'2026-04-12 07:06:00','2026-11-23 17:04:34'),(17,2,1,'Baursak & Co','A new tea house from the team behind Dastarkhan House: fresh baursaks, samsa and Kazakh tea for breakfast and evening gatherings.','Aktobe','Zhankozha Batyr St 88','+7 7132 10 20 30',NULL,1,'08:00:00','22:00:00','https://images.unsplash.com/photo-1606491956689-2ea866880c84?auto=format&fit=crop&w=1200&q=70','pending',0,'2026-11-20 07:01:00','2026-11-23 17:04:34'),(18,5,17,'Night Owl Shawarma','Late-night shawarma kiosk. Address and photos to be added.','Aktobe','Street food kiosk',NULL,NULL,1,'18:00:00','04:00:00','https://images.unsplash.com/photo-1626700051175-6818013e1d4f?auto=format&fit=crop&w=1200&q=70','rejected',0,'2026-11-19 07:58:00','2026-11-23 17:04:34');
/*!40000 ALTER TABLE `restaurants` ENABLE KEYS */;
UNLOCK TABLES;

